  del_acct_forever_q:'Xóa vĩnh viễn tài khoản này?', adm_del_user_d:'Người dùng và tất cả những gì họ có sẽ bị xóa sạch — tin đăng, ảnh và mọi trò chuyện. Họ SẼ KHÔNG còn trong danh sách. Không thể hoàn tác.', acct_deleted_good:'Đã xóa vĩnh viễn tài khoản',
  setup_tag:'Thiết lập một lần — bảo mật nền tảng trước khi người thuê và chủ nhà tham gia.', setup_pill:'Thiết lập một lần', setup_h1:'Tạo tài khoản quản trị',
  setup_sub:'Trang này chỉ dùng được một lần — tài khoản đầu tiên tạo ở đây sẽ trở thành Quản trị viên của nền tảng. Hãy làm ngay sau khi triển khai.', setup_name:'Tên quản trị', setup_name_ph:'vd: Isaac',
  setup_phone_ph:'vd: +2547… (mã quốc gia)', setup_user_ph:'admin', setup_go:'Tạo quản trị & đăng nhập',
  welc_to:'Chào mừng đến với', welc_sk_sub:'Tài khoản của bạn đã sẵn sàng — đây là cách tìm nhà an toàn.', welc_ll_sub:'Tài khoản của bạn đã sẵn sàng — đây là cách cho thuê nhanh và an toàn.',
  welc_scam_t:'Chưa THẤY nhà thì đừng bao giờ gửi tiền.', welc_scam_d:'Không cọc, không phí đặt chỗ, không đặt trước — không gì cả. Hãy đến xem nhà trước, rồi trả tiền trực tiếp cho chủ nhà.', welc_g1:'<b>Tìm kiếm</b> — gõ tên thành phố hoặc quốc gia vào thanh tìm kiếm, hoặc chạm <b>Dùng vị trí hiện tại</b> để thấy những nhà còn trống gần bạn nhất trước tiên.',
  welc_g2:'<b>Mở &amp; so sánh</b> — kiểm tra ảnh, giá thuê, tiền cọc, nước và điện ở từng tin trước khi nhắn tin.', welc_g3:'<b>Trò chuyện</b> — nhắn tin cho chủ nhà trong ứng dụng hoặc qua WhatsApp. Hỏi gì cũng được — khi nào xem nhà, gồm những gì.', welc_g4:'<b>Ghé &amp; xem</b> — hãy đến xem nhà vào ban ngày, tốt nhất là đi cùng bạn bè. Chủ nhà thật sẽ rất hoan nghênh điều đó.',
  welc_g5:'<b>Chỉ trả tiền sau khi xem</b> — tiền cọc và tiền thuê chuyển thẳng cho chủ nhà, không bao giờ qua HuntIn.', welc_flags_t:'Dấu hiệu đáng ngờ — rút ngay', welc_f1:'Ai đó thúc bạn gửi tiền cho một căn nhà bạn chưa từng thấy.',
  welc_f2:'Những câu chuyện kiểu “trả tiền trước để đặt chỗ”, hoặc giá thuê rẻ bất thường so với khu đó.', welc_f3:'Từ chối gọi video hoặc xem nhà trực tiếp.', welc_report:'Thấy tin đăng giả? Mở nó ra và chạm <b>Báo cáo</b> — mọi báo cáo đều được quản trị viên xem xét.',
  welc_find_btn:'Tìm nhà gần tôi', welc_ll_t:'4 bước để cho thuê nhanh hơn', welc_l1:'<b>Xác minh</b> — Hồ sơ → xác minh: tải lên giấy tờ tùy thân và ảnh chứng minh quyền sở hữu. Quản trị viên duyệt xong, bạn nhận huy hiệu xanh và <b>đăng 5 tin thay vì 2</b>. Người thuê tin tưởng huy hiệu — chủ nhà đã xác minh nhận được nhiều trò chuyện hơn.',
  welc_l2:'<b>Đăng tin nhà bạn</b> — chạm <b>Đăng tin mới</b>: 8 bước nhanh chóng. Chọn quốc gia & thành phố, ghim đúng vị trí cổng nhà lên bản đồ, thêm từ 3 ảnh rõ nét chụp ban ngày.', welc_l3:'<b>Đẩy tin miễn phí</b> — chạm một lần là tin của bạn ghim ở <b>vị trí trên đầu trong {n} ngày</b> với mọi người thuê đang xem quốc gia của bạn. Miễn phí khi HuntIn còn mới.', welc_l4:'<b>Trả lời nhanh</b> — nhà nào chủ nhà trả lời nhanh thì cho thuê nhanh hơn nhiều. Trò chuyện nằm trong tab Trò chuyện của bạn.',
  welc_ll_note:'<b>Hãy là chủ nhà mà người thuê tin tưởng:</b> đừng bao giờ đòi tiền trước khi xem nhà, và gặp người thuê tại nhà vào ban ngày. HuntIn không bao giờ thay bạn thu tiền.', welc_post_btn:'Đăng tin nhà đầu tiên', welc_verify_btn:'Xác minh ngay',
