  setup_tag:'Konfiguracja jednorazowa — zabezpiecz swoją platformę, zanim dołączą najemcy i wynajmujący.', setup_pill:'Konfiguracja jednorazowa', setup_h1:'Utwórz konto administratora',
  setup_sub:'Ta strona działa tylko raz — pierwsze konto utworzone tutaj zostaje administratorem platformy. Zrób to zaraz po wdrożeniu.', setup_name:'Nazwa administratora', setup_name_ph:'np. Isaac',
